css:
.comp-adv-container { padding: 24px; background: #faf8f3; min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2744; max-width: 1400px; margin: 0 auto; }
.comp-adv-header { background: linear-gradient(135deg, #264653 0%, #1a2744 100%); color: #faf8f3; padding: 32px 40px; border-radius: 4px; margin-bottom: 24px; box-shadow: 0 4px 16px rgba(26,39,68,0.18); }
.comp-adv-header h1 { font-size: 1.8rem; font-weight: 700; margin: 0; letter-spacing: 0.02em; }
.comp-adv-subtitle { color: #f4c693; margin-top: 6px; font-size: 0.95rem; font-style: italic; }
.comp-adv-period-counter { background: #1a2744; color: #f4a261; padding: 12px 24px; border-radius: 4px; font-weight: 700; text-align: center; margin-bottom: 24px; font-size: 1.05rem; letter-spacing: 0.08em; text-transform: uppercase; }
.comp-adv-briefing { background: #ffffff; border-left: 4px solid #f4a261; padding: 20px 24px; border-radius: 4px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); }
.comp-adv-briefing-label { font-size: 0.72rem; color: #6b7280; letter-spacing: 0.12em; text-transform: uppercase; margin-bottom: 8px; font-weight: 700; }
.comp-adv-briefing-text { font-size: 1rem; color: #1a2744; line-height: 1.6; }
.comp-adv-briefing-text strong { color: #b54a30; }
.comp-adv-countries { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 24px; }
.comp-adv-country { background: #ffffff; border-radius: 4px; padding: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); position: relative; border-top: 4px solid; }
.comp-adv-costaria { border-top-color: #e76f51; }
.comp-adv-boravia { border-top-color: #2a9d8f; }
.comp-adv-country-flag { font-size: 2rem; margin-bottom: 4px; line-height: 1; }
.comp-adv-country h2 { font-size: 1.3rem; font-weight: 700; margin: 0 0 12px 0; color: #1a2744; }
.comp-adv-costaria h2 { color: #b54a30; }
.comp-adv-boravia h2 { color: #1d6a60; }
.comp-adv-country-meta { display: flex; gap: 18px; font-size: 0.85rem; color: #6b7280; margin-bottom: 12px; }
.comp-adv-country-rates { background: #f8f5ee; padding: 12px 16px; border-radius: 4px; font-size: 0.85rem; margin-bottom: 16px; line-height: 1.6; }
.comp-adv-opp-cost { font-weight: 700; margin-top: 6px; padding-top: 6px; border-top: 1px dashed #d4c8b0; color: #1a2744; }
.comp-adv-kpi-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.comp-adv-kpi-card { background: #f8f5ee; padding: 14px 16px; border-radius: 4px; border-left: 3px solid #c8b89a; }
.comp-adv-kpi-cons { border-left-color: #f4a261; background: #fef6ec; }
.comp-adv-boravia .comp-adv-kpi-cons { border-left-color: #2a9d8f; background: #ebf6f2; }
.comp-adv-kpi-label { font-size: 0.7rem; color: #6b7280; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 4px; font-weight: 700; }
.comp-adv-kpi-value { font-size: 1.4rem; font-weight: 700; color: #1a2744; transition: color 0.2s ease; }
.comp-adv-decision { background: #f4eee0; padding: 14px 16px; border-radius: 4px; }
.comp-adv-decision label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-decision input[type="range"] { width: 100%; margin: 8px 0; accent-color: #e76f51; }
.comp-adv-boravia .comp-adv-decision input[type="range"] { accent-color: #2a9d8f; }
.comp-adv-slider-value { font-size: 0.85rem; color: #6b7280; text-align: center; }
.comp-adv-trade-panel, .comp-adv-policy-panel { background: #ffffff; border-radius: 4px; padding: 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); border-top: 4px solid #1a2744; }
.comp-adv-trade-panel h3, .comp-adv-policy-panel h3, .comp-adv-world h3, .comp-adv-history h3 { margin: 0 0 12px 0; font-size: 1.05rem; font-weight: 700; color: #1a2744; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-trade-info, .comp-adv-policy-info { font-size: 0.9rem; color: #6b7280; margin-bottom: 16px; font-style: italic; line-height: 1.5; }
.comp-adv-trade-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.comp-adv-trade-input label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-trade-input input { width: 100%; background: #faf8f3; border: 1px solid #c8b89a; color: #1a2744; padding: 10px 12px; border-radius: 4px; font-size: 1rem; font-family: inherit; }
.comp-adv-trade-input input:focus { outline: none; border-color: #f4a261; box-shadow: 0 0 0 2px rgba(244,162,97,0.2); }
.comp-adv-trade-output { background: #f8f5ee; padding: 12px 16px; border-radius: 4px; font-size: 0.95rem; display: flex; gap: 32px; flex-wrap: wrap; color: #1a2744; }
.comp-adv-trade-output strong { color: #b54a30; font-size: 1.05rem; }
.comp-adv-displaced-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.comp-adv-displaced-card { background: #fef6ec; padding: 14px 18px; border-radius: 4px; border-left: 3px solid #e76f51; }
.comp-adv-displaced-card:nth-child(2) { background: #ebf6f2; border-left-color: #2a9d8f; }
.comp-adv-displaced-label { font-size: 0.7rem; color: #6b7280; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 4px; font-weight: 700; }
.comp-adv-displaced-value { font-size: 1.4rem; font-weight: 700; color: #b54a30; }
.comp-adv-displaced-card:nth-child(2) .comp-adv-displaced-value { color: #1d6a60; }
.comp-adv-policy-panel label { display: block; font-size: 0.78rem; font-weight: 700; color: #1a2744; margin-bottom: 6px; letter-spacing: 0.04em; text-transform: uppercase; }
.comp-adv-policy-panel select { width: 100%; background: #faf8f3; border: 1px solid #c8b89a; color: #1a2744; padding: 10px 12px; border-radius: 4px; font-size: 0.95rem; font-family: inherit; }
.comp-adv-policy-panel select:focus { outline: none; border-color: #f4a261; box-shadow: 0 0 0 2px rgba(244,162,97,0.2); }
.comp-adv-policy-panel select option { background: #ffffff; color: #1a2744; }
.comp-adv-world { background: #ffffff; border-radius: 4px; padding: 20px 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); border-top: 4px solid #2a9d8f; }
.comp-adv-world-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.comp-adv-world-card { background: #ebf6f2; padding: 18px 22px; border-radius: 4px; border-left: 3px solid #2a9d8f; }
.comp-adv-world-label { font-size: 0.72rem; color: #6b7280; letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 6px; font-weight: 700; }
.comp-adv-world-value { font-size: 1.7rem; font-weight: 700; color: #1d6a60; }
.comp-adv-actions { display: flex; gap: 12px; margin-bottom: 24px; align-items: center; }
.comp-adv-actions .btn-primary { background: #e76f51; border-color: #e76f51; font-weight: 700; letter-spacing: 0.06em; padding: 12px 28px; text-transform: uppercase; font-size: 0.85rem; border-radius: 4px; transition: background 0.2s ease, transform 0.2s ease; }
.comp-adv-actions .btn-primary:hover { background: #d65a3e; border-color: #d65a3e; transform: translateY(-1px); }
.comp-adv-actions .btn-outline-secondary { color: #6b7280; border-color: #c8b89a; background: transparent; font-size: 0.8rem; }
.comp-adv-actions .btn-outline-secondary:hover { background: #f8f5ee; color: #1a2744; }
.comp-adv-history { background: #ffffff; border-radius: 4px; padding: 20px 24px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); }
.comp-adv-history table { font-size: 0.85rem; color: #1a2744; margin-bottom: 0; }
.comp-adv-history table th { background: #1a2744; color: #faf8f3; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; font-size: 0.7rem; padding: 10px 12px; border: none; }
.comp-adv-history table td { padding: 10px 12px; border-color: #ece4d3; }
.comp-adv-charts { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.comp-adv-chart-wrap { background: #ffffff; border-radius: 4px; padding: 16px; box-shadow: 0 2px 8px rgba(38,70,83,0.08); height: 340px; position: relative; }
@media (max-width: 768px) { .comp-adv-countries, .comp-adv-trade-controls, .comp-adv-displaced-grid, .comp-adv-world-grid, .comp-adv-charts { grid-template-columns: 1fr; } .comp-adv-container { padding: 16px; } .comp-adv-header { padding: 22px 24px; } .comp-adv-header h1 { font-size: 1.35rem; } .comp-adv-chart-wrap { height: 280px; } }

/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.comp-adv-container :focus-visible,
.comp-adv-container select:focus-visible,
.comp-adv-container input:focus-visible,
.comp-adv-container button:focus-visible {
    outline: 3px solid #264653;
    outline-offset: 2px;
    border-radius: 3px;
}
.comp-adv-actions { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.comp-adv-completion {
    background: #ffffff;
    border: 1px solid #e0dbcf;
    border-left: 6px solid #264653;
    border-radius: 4px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #1a2744;
}
.comp-adv-debrief h3 { margin: 0 0 10px; font-size: 1.15rem; }
.comp-adv-debrief-headline { font-size: 1rem; margin-bottom: 14px; }
.comp-adv-debrief-list {
    list-style: none; padding: 0; margin: 0 0 14px;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 8px;
}
.comp-adv-debrief-list li {
    display: flex; justify-content: space-between; gap: 12px;
    background: #faf8f3; border: 1px solid #e0dbcf; border-radius: 4px; padding: 8px 12px;
}
.comp-adv-debrief-k { color: #55606f; font-size: 0.82rem; }
.comp-adv-debrief-v { font-weight: 700; }
.comp-adv-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; }
@media (prefers-reduced-motion: reduce) {
    .comp-adv-container *,
    .comp-adv-container *::before,
    .comp-adv-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

