        getHint(state, results) {
            if (!results) return null;
            var completed = results.period;
            if (completed === 1) {
                return window.mySimulation.t('hint_after_round1');
            }
            if (completed === 2) {
                if (results.tradePrice && (results.tradePrice < 1 || results.tradePrice > 2)) {
                    return window.mySimulation.t('hint_outside_corridor');
                }
                var b = state.domainState.autarkyBaseline;
                if (b && (results.worldMango + results.worldSoft) > (b.worldMango + b.worldSoft) * 1.02) {
                    return window.mySimulation.t('hint_gains_realised');
                }
                return window.mySimulation.t('hint_specialise_more');
            }
            if (completed === 3) {
                var p = state.decisions.policy || 'e';
                if (p === 'd') return window.mySimulation.t('hint_policy_tariff');
                if (p === 'e') return window.mySimulation.t('hint_policy_nothing');
                return window.mySimulation.t('hint_policy_compensation');
            }
            return null;
        }

