        getPerformanceSummary(history) {
            if (!history.length) return {};
            var insights = [];
            var r1 = history.find(function(h) { return h.results && h.results.period === 1; });
            var r2 = history.find(function(h) { return h.results && h.results.period === 2; });
            var r3 = history.find(function(h) { return h.results && h.results.period === 3; });
            var totalGain = 0;
            if (r1 && r2) {
                var r1Total = r1.results.worldMango + r1.results.worldSoft;
                var r2Total = r2.results.worldMango + r2.results.worldSoft;
                if (r2Total > r1Total * 1.02) {
                    insights.push(window.mySimulation.t('summary_gain_realised'));
                } else {
                    insights.push(window.mySimulation.t('summary_no_gain'));
                }
                totalGain = r2Total - r1Total;
            }
            // Composite over the three things this simulation actually teaches. The old
            // verdict looked only at the price corridor and the policy letter, so a run
            // that never traded at all scored top marks. Gain is now weighted first and
            // caps the result when nothing was realised.
            var r1World = (r1 && r1.results) ? (r1.results.worldMango + r1.results.worldSoft) : 0;
            var r2World = (r2 && r2.results) ? (r2.results.worldMango + r2.results.worldSoft) : 0;
            var gainPct = r1World > 0 ? ((r2World - r1World) / r1World) : 0;
            // Full specialisation (Costaria 100 percent mangoes, Boravia 0 percent) is worth
            // +1.0 percent world consumption in this model, so 1.0 percent is full marks.
            var gainScore = Math.max(0, Math.min(1, gainPct / 0.01));

            var traded = !!(r2 && r2.results && r2.results.costExportMangoes > 0);
            var price = (r2 && r2.results) ? r2.results.tradePrice : 0;
            // A price ratio only earns credit if goods actually moved at it.
            var priceScore = (traded && price >= 1 && price <= 2) ? 1 : 0;

            var policy = (r3 && r3.decisions) ? r3.decisions.policy : null;
            var policyScore = 0;
            if (policy === 'a' || policy === 'b' || policy === 'c') policyScore = 1;
            else if (policy === 'd') policyScore = 0.3;

            var overall = Math.round((gainScore * 45) + (priceScore * 30) + (policyScore * 25));
            if (gainScore <= 0) overall = Math.min(overall, 45);
            overall = Math.max(0, Math.min(100, overall));

            var performance = 'beginner';
            if (overall >= 80) performance = 'excellent';
            else if (overall >= 60) performance = 'good';
            else if (overall >= 40) performance = 'developing';
            var perfKey = 'perf_' + performance;

            if (policyScore === 1 && gainScore > 0) {
                insights.push(window.mySimulation.t('summary_compensation_chosen'));
            }
            insights.push(window.mySimulation.t('summary_canonical'));
            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                totalGain: totalGain,
                gainPct: Math.round(gainPct * 1000) / 10,
                tradePrice: price,
                policy: policy || '',
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights: insights
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                var v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        _isRunComplete(period) {
            var st = (window.mySimulation && window.mySimulation.state) || {};
            var maxP = parseInt(st.maxPeriods, 10) || 3;
            var hist = Array.isArray(st.history) ? st.history : [];
            if (hist.length >= maxP) return true;
            return (period || 1) > maxP;
        }

