            var sel = document.getElementById('policySelect');
            if (sel && dec.policy) sel.value = dec.policy;
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var rows = [
                [t('debrief_gain'), (s.gainPct >= 0 ? '+' : '') + esc(s.gainPct) + '%'],
                [t('debrief_price'), esc(s.tradePrice)],
                [t('debrief_policy'), esc((s.policy || '-').toUpperCase())]
            ].map(function(r) {
                return '<li><span class="comp-adv-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="comp-adv-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            var ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="comp-adv-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="comp-adv-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="comp-adv-debrief-list">' + rows + '</ul>' +
                     '<div class="comp-adv-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

